package com.agacostays.billing.event.producer;import com.agacostays.billing.constants.KafkaTopicConstants;import com.agacostays.billing.event.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Component;@Component public class BillingEventProducer{private final KafkaTemplate<String,Object> k;public BillingEventProducer(KafkaTemplate<String,Object> k){this.k=k;}public void finalBill(FinalBillGeneratedEvent e){k.send(KafkaTopicConstants.BILLING_EVENTS,e.billId().toString(),e);}public void invoice(InvoiceGeneratedEvent e){k.send(KafkaTopicConstants.BILLING_EVENTS,e.billId().toString(),e);}public void paid(BillPaidEvent e){k.send(KafkaTopicConstants.BILLING_EVENTS,e.billId().toString(),e);}public void cancelled(BillCancelledEvent e){k.send(KafkaTopicConstants.BILLING_EVENTS,e.billId().toString(),e);}}
